    "dialogue": "\"Dạ tuyệt vời quá, chúc mừng anh/chị đã quyết định bắt tay cùng Má Hải, em gửi hợp đồng qua Zalo mình xem rồi hoàn tất cọc 2 triệu để công ty chuẩn bị xe kịp ngày khai trương nhé ạ!\""
