    "dialogue": "\"Dạ anh/chị muốn xem qua hợp đồng và chốt cọc trong sáng nay hay đầu giờ chiều để em hỗ trợ làm thủ tục giữ vị trí điểm bán cho mình anh/chị nhé ạ!\""
