    "sectionName": "Kỹ Năng Tư Vấn, Sàng Lọc & Dẫn Dắt Khách Hàng",
    "question": "Khi tư vấn giải pháp mở xe Bánh Mì Má Hải theo nhu cầu và phương tiện sẵn có của khách, nhận định nào sau đây là KHÔNG ĐÚNG?",
