        "key": "c",
        "text": "Câu hỏi \"Ngoài ra mình còn điều gì băn khoăn nữa không ạ?\" giúp gom và gỡ sạch toàn bộ khúc mắc phụ, tránh phát sinh lý do dây chuyền."
