    "dialogue": "\"Dạ em hiểu là lúc khởi đầu ai cũng có những khó khăn về vốn, anh/chị cứ yên tâm để em chia sẻ thêm các giải pháp nhẹ vốn nhất của bên em để mình tham khảo trước anh/chị nhé ạ!\""
