    "question": "Khi tư vấn cho nhóm khách hàng muốn nhìn thấy rõ bài toán thu nhập thực tế và khả năng hoàn vốn trước khi quyết định mở xe, người tư vấn cần tập trung vào những luận điểm nào?",
