        "text": "Cam kết 2 (Niềm tin thương hiệu): Đứng trên vai người khổng lồ uy tín 13 năm Shark Tank (Lợi thế 3) và Sản phẩm chuẩn hóa có kiểm nghiệm khoa học (Lợi thế 4)."
