    "dialogue": "\"Trước khi nhấc máy, mình dành 1 phút xem lại khách tên gì, ở khu vực nào và lần trước đã trao đổi đến đâu để khi cất lời là tạo được ấn tượng thân tình, chu đáo ngay từ câu chào đầu tiên nhé ạ!\""
