    "dialogue": "\"Dạ chính sách Má Hải rõ ràng lắm: 0 đồng phí tháng, 0% chia doanh thu và giá nguyên liệu luôn bình ổn, mình bán được bao nhiêu tiền lời là giữ trọn 100% nuôi gia đình nhé ạ!\""
